arguments:
{"script":"mkdir -p logs
for i in 0 1 2 3 4 5 6; do
  d=$(date -d "-$i day" +%F)
  f=logs/log_${d}.txt
  : > "$f"
  for j in $(seq 1 50); do
    case $((RANDOM%10)) in
      0|1) echo "Error: something failed at line $j" >>"$f";;
      2|3) echo "error occurred in module $((RANDOM%5))" >>"$f";;
      4|5) echo "Warning: check config $j" >>"$f";;
      6|7|8|9) echo "info: operation $j completed" >>"$f";;
    esac
  done
done
grep -oi "error" logs/* | wc -l
"}
